pub fn buntaghashbuf_make(buf: *BuntagHashBuf, patch_hash: u64) [:0]u8 {
        _ = @memcpy(buf[0..bun_hash_tag.len], bun_hash_tag);
        const digits = ((std.fmt.bufPrint(buf[bun_hash_tag.len..], "{x}", .{ patch_hash })) catch unreachable);
        buf[cp_cast_int(usize, (bun_hash_tag.len + digits.len))] = 0;
        const bunhashtag = buf[0..(bun_hash_tag.len + digits.len) :0];
        return bunhashtag;
}

pub fn fmtStorePath(str: []const u8) StorePathFormatter {
        return StorePathFormatter{ .str = str };
}

pub fn initializeStore() void {
        if (initialized_store) {
            _ = JSAst.Expr.Data.Store.reset();
            _ = JSAst.Stmt.Data.Store.reset();
            return;
        }
        initialized_store = true;
        _ = JSAst.Expr.Data.Store.create();
        _ = JSAst.Stmt.Data.Store.create();
}

pub fn initializeMiniStore() void {
        if ((mini_store_instance == null)) {
            var mini_store = bun.handleOom(bun.default_allocator.create(MiniStore));
            _ = &mini_store;
            mini_store.* = MiniStore{ .heap = bun.MimallocArena.init(), .memory_allocator = undefined };
            mini_store.memory_allocator = JSAst.ASTMemoryAllocator{ .allocator = mini_store.heap.allocator() };
            _ = mini_store.memory_allocator.reset();
            mini_store_instance = mini_store;
            _ = mini_store.memory_allocator.push();
        } else {
            var mini_store = mini_store_instance.?;
            _ = &mini_store;
            if ((mini_store.memory_allocator.stack_allocator.fixed_buffer_allocator.end_index >= (mini_store.memory_allocator.stack_allocator.fixed_buffer_allocator.buffer.len -| 1))) {
                _ = mini_store.heap.deinit();
                mini_store.heap = bun.MimallocArena.init();
                mini_store.memory_allocator.allocator = mini_store.heap.allocator();
            }
            _ = mini_store.memory_allocator.reset();
            _ = mini_store.memory_allocator.push();
        }
}
